package com.fasterxml.jackson.databind.deser.std;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.JsonParser;
import com.fasterxml.jackson.core.JsonToken;
import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.DeserializationContext;
import com.fasterxml.jackson.databind.annotation.JacksonStdImpl;
import com.fasterxml.jackson.databind.deser.ContextualDeserializer;
import com.fasterxml.jackson.databind.deser.ObjectBuffer;
import com.fasterxml.jackson.databind.deser.std.StringArrayDeserializer;
import com.fasterxml.jackson.databind.deser.std.StringDeserializer;
import com.fasterxml.jackson.databind.jsontype.TypeDeserializer;
import com.fasterxml.jackson.databind.util.ObjectBuffer;
import java.io.*;
import java.io.IOException;
import java.lang.reflect.Field;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mock;
import org.mockito.MockitoAnnotations;
import static org.junit.Assert.*;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.eq;
import static org.mockito.Mockito.*;

public class StringArrayDeserializer__deserializeCustom_TriageGen0Test {

    private StringArrayDeserializer deserializer;

    @Mock
    private JsonParser jp;

    @Mock
    private DeserializationContext ctxt;

    @Mock
    private ObjectBuffer buffer;

    @Mock
    private StringDeserializer elementDeserializer;

    @Before
    public void setUp() throws Exception {
        MockitoAnnotations.initMocks(this);
        deserializer = new StringArrayDeserializer();

        // Use reflection to set the protected field _elementDeserializer
        Field field = StringArrayDeserializer.class.getDeclaredField("_elementDeserializer");
        field.setAccessible(true);
        field.set(deserializer, elementDeserializer);

        // Setup buffer behavior
        when(ctxt.leaseObjectBuffer()).thenReturn(buffer);
        when(buffer.resetAndStart()).thenReturn(new Object[1]); // Small buffer to force resizing
        when(buffer.appendCompletedChunk(any())).thenReturn(new Object[2]);
        when(buffer.completeAndClearBuffer(any(), anyInt(), eq(String.class))).thenAnswer(invocation -> {
            Object[] chunk = invocation.getArgument(0);
            int len = invocation.getArgument(1);
            String[] result = new String[len];
            for (int i = 0; i < len; i++) {
                result[i] = (String) chunk[i];
            }
            return result;
        });
    }

    /**
     * Helper to invoke the protected method via reflection
     */
    private String[] invokeDeserializeCustom(JsonParser jp, DeserializationContext ctxt) throws Exception {
        java.lang.reflect.Method method = StringArrayDeserializer.class.getDeclaredMethod("_deserializeCustom", JsonParser.class, DeserializationContext.class);
        method.setAccessible(true);
        return (String[]) method.invoke(deserializer, jp, ctxt);
    }

    @Test
    public void testDeserializeCustom_EmptyArray() throws Exception {
        when(jp.nextToken()).thenReturn(JsonToken.END_ARRAY);

        String[] result = invokeDeserializeCustom(jp, ctxt);

        assertEquals(0, result.length);
        verify(ctxt).returnObjectBuffer(buffer);
    }

    @Test
    public void testDeserializeCustom_SingleElement() throws Exception {
        when(jp.nextToken())
                .thenReturn(JsonToken.START_ARRAY)
                .thenReturn(JsonToken.VALUE_STRING)
                .thenReturn(JsonToken.END_ARRAY);

        when(elementDeserializer.deserialize(eq(jp), eq(ctxt))).thenReturn("hello");

        String[] result = invokeDeserializeCustom(jp, ctxt);

        assertArrayEquals(new String[]{"hello"}, result);
        verify(ctxt).returnObjectBuffer(buffer);
    }

    @Test
    public void testDeserializeCustom_WithNull() throws Exception {
        when(jp.nextToken())
                .thenReturn(JsonToken.START_ARRAY)
                .thenReturn(JsonToken.VALUE_NULL)
                .thenReturn(JsonToken.END_ARRAY);

        String[] result = invokeDeserializeCustom(jp, ctxt);

        assertArrayEquals(new String[]{null}, result);
        verify(elementDeserializer, never()).deserialize(any(), any());
    }

    @Test
    public void testDeserializeCustom_TriggerBufferResize() throws Exception {
        // Buffer size is 1 (set in setUp). We provide 3 elements to trigger appendCompletedChunk.
        when(jp.nextToken())
                .thenReturn(JsonToken.START_ARRAY)
                .thenReturn(JsonToken.VALUE_STRING) // ix=0
                .thenReturn(JsonToken.VALUE_STRING) // ix=1 -> triggers resize
                .thenReturn(JsonToken.VALUE_STRING) // ix=0 (in new chunk)
                .thenReturn(JsonToken.END_ARRAY);

        when(elementDeserializer.deserialize(eq(jp), eq(ctxt)))
                .thenReturn("a")
                .thenReturn("b")
                .thenReturn("c");

        // Mocking the append sequence
        Object[] chunk1 = new Object[]{"a"};
        Object[] chunk2 = new Object[]{"b", "c"};

        // We need to simulate the logic where the buffer grows
        // In the actual code: chunk = buffer.appendCompletedChunk(chunk); ix = 0;
        // We'll use a more complex answer to simulate the stateful buffer behavior
        when(buffer.resetAndStart()).thenReturn(new Object[1]);
        when(buffer.appendCompletedChunk(any())).thenReturn(chunk2);

        String[] result = invokeDeserializeCustom(jp, ctxt);

        // The result is constructed by completeAndClearBuffer which takes the last 'chunk' passed to it
        // In the loop: 
        // 1. ix=0, val="a", chunk[0]="a", ix=1
        // 2. nextToken -> VALUE_STRING. ix(1) >= chunk.length(1) is true.
        // 3. chunk = appendCompletedChunk(chunk), ix=0.
        // 4. chunk[0]="b", ix=1
        // 5. nextToken -> VALUE_STRING. ix(1) >= chunk.length(2) is false.
        // 6. chunk[1]="c", ix=2
        // 7. nextToken -> END_ARRAY.
        // 8. completeAndClearBuffer(chunk, 2, String.class)

        assertArrayEquals(new String[]{"b", "c"}, result); 
        // Note: The logic in the method actually loses the first chunk if not handled by the buffer implementation 
        // correctly, but we are testing the code as written. In the code: chunk is replaced by the new chunk.
    }

    @Test(expected = IOException.class)
    public void testDeserializeCustom_ThrowsIOException() throws Exception {
        when(jp.nextToken()).thenThrow(new IOException("Mock IO Error"));

        invokeDeserializeCustom(jp, ctxt);
    }
}
